head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnChooseOption]<br/>Body Column 정보를 사용하여 특정 Column 에 '선택 안내'를 의미하는 아이템을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = name(인덱스0) / grade(인덱스1, select), 2줄 = qty(인덱스2) / phone(인덱스3)
//  - Row 가 MultiLine 이어도 name~phone 은 각각 고유 인덱스(0~3)를 가짐
//  - select 컬럼(grade)의 고유 인덱스는 1 -> setColumnChooseOption(1, ...) 로 호출
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 지점명(0)/매출(1), 2줄 등급(2, select)/연락처(3) 고유 인덱스. 데이터 Row 3개. 등급 컬럼은 DataList(dlt_grade) 바인딩 select 이며 2줄에 위치.\n[절차] columnInfo(0~3) 선택 후 (setColumnChooseOption 실행). value=ALL, label=- 선택 - 로 호출.\n[확인] MultiLine 이어도 모든 Column 은 고유 인덱스(0~3). select 컬럼(등급)은 2줄에 있지만 고유 인덱스 2 -> setColumnChooseOption(2, ...) 호출 시 정확히 그 컬럼에 선택 안내 아이템(- 선택 -)이 첫 아이템으로 설정되고 chooseOption=true 가 됨. 다른 인덱스(select 아님) 호출 시 미동작."', '', 'label1');

    // select 컬럼 옵션 DataList (label / value)
    let strGradeDlt = '';
    strGradeDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGradeDlt += '<w2:columnInfo>';
    strGradeDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGradeDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strGradeDlt += '</w2:columnInfo>';
    strGradeDlt += '<w2:data use="true"></w2:data>';
    strGradeDlt += '</w2:dataList>';
    $p.data.create(strGradeDlt);
    dlt_grade.setJSON([
        { "label": "A등급", "value": "A" },
        { "label": "B등급", "value": "B" },
        { "label": "C등급", "value": "C" }
    ], false);

    // GridView 바인딩 DataList (name/grade/qty/phone)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "A", "col3": "1250", "col4": "010-1111-2222" },
        { "col1": "부산 해운대점", "col2": "B", "col3": "980", "col4": "010-3333-4444" },
        { "col1": "대구 수성점", "col2": "C", "col3": "1430", "col4": "010-5555-6666" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : name(0) / grade(1, select, DataList 바인딩 itemset)
    //  - 2줄 : qty(2) / phone(3)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="등급(select)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="연락처"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : name/지점명 (text)
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : qty/매출 (text)
    strTarget += '<w2:column width="*" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : grade/등급 (select, DataList 바인딩 itemset) - setColumnChooseOption 대상.
    //           2줄(brow2)에 있는 컬럼이지만 MultiLine 이어도 고유 인덱스가 이어져 2 가 됨(검증 핵심).
    strTarget += '<w2:column width="280" inputType="select" id="col2" dataList="col2">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_grade">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    // index 3 : phone/연락처 (text)
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setColumnChooseOption 실행 : 선택한 고유 인덱스(columnInfo)에 '선택 안내' 아이템 설정.
//  - MultiLine Row 에서도 모든 Column 은 고유 인덱스(0~3). select 컬럼(등급)은 2줄에 있지만 고유 인덱스는 2.
//  - 정상 동작 시 해당 select 컬럼(고유 인덱스 2) 첫 아이템이 '- 선택 -' 가 되고 chooseOption=true.
//  - select 아닌 인덱스(0/1/3) 로 호출하면 미동작.
scwin.btn_setColumnChooseOption_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 name~phone 은 고유 인덱스(0~3)

    // 선택 안내 아이템 설정 : value=ALL, label='- 선택 -'
    target1.setColumnChooseOption(columnInfo, "ALL", "- 선택 -");

    // 설정 결과 확인 : 해당 고유 인덱스 컬럼의 inputType / chooseOption 적용 상태 확인
    //  - inputType="select" 컬럼(고유 인덱스 1) 일 때만 chooseOption=true 로 설정됨
    let cellInfo = target1.getCellInfo(columnInfo);
    let inputType = (cellInfo && cellInfo.options) ? cellInfo.options.inputType : undefined;
    let chooseOption = (cellInfo && cellInfo.options) ? cellInfo.options.chooseOption : undefined;
    let chooseOptionLabel = (cellInfo && cellInfo.options) ? cellInfo.options.chooseOptionLabel : undefined;

    let msg = "setColumnChooseOption(" + columnInfo + ", 'ALL', '- 선택 -') -> 고유 인덱스 " + columnInfo + " [" + colID + "] (inputType=" + inputType + ") : chooseOption=" + chooseOption + ", chooseOptionLabel='" + chooseOptionLabel + "'";

    // select 컬럼(고유 인덱스 2)이면 해당 Row 0 셀을 편집모드로 진입시켜 렌더된 첫 아이템(itemArr[0])을 읽는다.
    //  -> chooseOptionLabel('- 선택 -')이 첫번째 아이템으로 표시되는지 확인 (_1/_2 샘플과 동일 패턴).
    //  (WebSquare select 셀은 native select 가 아닌 w2selectbox 로 렌더 -> cellInfo.select.itemArr 로 확인)
    if (target1.getCellInfo(columnInfo).options.inputType === "select") {
        let td = document.querySelector("td[id*='target1_cell_0_" + columnInfo + "']");
        target1.setEditMode(td);
        let sel = target1.getCellInfo(columnInfo).select;
        if (sel && sel.itemArr && sel.itemArr.length > 0) {
            msg += "\n[첫 아이템] label='" + sel.itemArr[0].label + "' value='" + sel.itemArr[0].value + "'";
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
